INSERT INTO "governance_documents" ("id","category","title","filename","file_url","doc_date","year","created_at","content") VALUES('76c1bb620266484c','bylaws','By-Laws of the Louisiana Chess Association (est. 2016)',NULL,NULL,'2016-09-01',NULL,'2026-07-07 17:58:35','<h2>Article I: Name and Purpose<br><br></h2><p>1. The name of this organization will be the Louisiana Chess Association. The organization shall be known by its name or the abbreviation "LCA."<br><br></p><p>2. The purpose of the LCA is to promote chess within Louisiana. To this end, the LCA shall be affiliated with the United States Chess Federation (USCF) or any successor organization and be the USCF''s official state affiliate for the state of Louisiana so long as the USCF or any such successor organization permits.<br><br></p><p>3. The LCA shall not be operated for profit. No part of its dues, contributions or net income shall benefit any individual. To the extent that the LCA awards cash prizes, trophies, or other awards at or for chess events, these cash prizes, trophies, and other awards shall not be considered benefits to any individual under this provision. To the extent that the LCA awards grants to any Louisiana chess players to represent Louisiana in national chess events, these grants, or any similar grants, shall not be considered benefits to any individual under this provision.<br><br></p><p>4. The LCA shall annually confer the title of State Chess Champion of Louisiana. The title of State Chess Champion of Louisiana shall be awarded to the highest finishing resident of Louisiana at the chess competition designated for this purpose. All residents of Louisiana shall be allowed to compete in this chess competition under the same terms and conditions. Nothing in this provision shall be construed to mean that non-residents of Louisiana cannot be allowed to participate in this chess competition, although non-residents of Louisiana shall not be eligible to win the title of State Chess Champion of Louisiana. The requirements for being a resident of Louisiana for the purpose of being eligible to be the state champion shall be determined by the membership. This requirement does not apply for residency issues that arise outside of the regular state championship, such as for scholastic players. The provision may be suspended by the Board of Directors if a natural disaster makes the holding of the competition unfeasible.<br><br></p><p>5. The LCA shall confer any other Louisiana chess titles as determined by the membership or the Board of Directors at such times as determined by the membership or the Board of Directors. The titles shall be awarded based upon chess competitions organized for the purpose of awarding such titles if feasible.<br><br><br></p><p>Article II: Membership<br><br></p><p>1. Any resident of Louisiana may become a regular member of the LCA by payment of the annual membership fee as set forth in this article.<br><br></p><p>2. Each regular member of the LCA shall be able to vote in all LCA elections.<br><br></p><p>3. Each regular member of the LCA shall receive any bulletin produced by the LCA for the duration of the membership<br><br></p><p>4. Membership in the LCA shall be required for participation in all LCA sanctioned or sponsored events. Non-residents of Louisiana shall be exempt from this provision. The membership, Board of Directors, or organizer of an LCA sanctioned or sponsored event may make an exception to this provision for events with participation restricted for scholastic (high school and below) individuals.<br><br></p><p>5. Annual dues for all types of memberships may only be changed by a rule passed by the membership. The Board of Directors shall have no power to change membership dues without approval of the membership.<br><br></p><p>6. Special membership classes, such as scholastic or out-of-state, with differing annual membership dues may be established by the membership or the Board of Directors. The rights and benefits of LCA members in special membership classes shall be established by the membership or the Board of Directors. Under no circumstances, however, shall the rights and benefits of members of a special membership class be greater than the rights and benefits of regular members.<br><br></p><p>7. Membership in the LCA may be revoked by a unanimous vote of the Board of Directors.<br><br><br></p><p>Article III: Governance<br><br></p><p>1. There shall be four officers of the LCA: the president, the vice-president, the secretary/treasurer, and the scholastic coordinator. The officers of the LCA shall be elected annually to one-year terms by the membership of the LCA at an LCA membership meeting during the competition to determine the State Chess Champion of Louisiana. If the holding of the competition to determine the State Chess Champion of Louisiana is not held due to a natural disaster, the officers of the LCA shall remain in office until the next such competition is held.<br><br></p><p>2. The LCA shall have a Board of Directors consisting of nine members. These members shall be the four officers of the LCA plus one regional representative from each of the five following regions:</p><p>New Orleans Metro Region consisting of the parishes of: Orleans; Jefferson; St. Bernard; Plaquemines; St. Charles; and St. Tammany.</p><p>Baton Rouge and East Central Region consisting of the parishes of: East Baton Rouge; West Baton Rouge; Ascension; Livingston; St. James; St. John the Baptist; Tangipahoa; Washington; St. Helena; East Feliciana; West Feliciana; Pointe Coupee; and Iberville.</p><p>Lafayette and South Central Region consisting of the parishes of: Lafayette; Iberia; St. Mary; St. Martin; Assumption; Terrebonne; Lafourche; Vermillion; Acadia; Evangeline; and St. Landry.</p><p>Lake Charles and Southwestern Region consisting of the parishes of: Calcasieu; Cameron; Jefferson Davis; Beauregard; and Allen.</p><p>North Region consisting of the parishes of: Caddo; DeSoto; Sabine; Vernon; Bossier; Red River; Natchitoches; Rapides; Webster; Claiborne; Bienville; Union; Lincoln; Jackson; Winn; Grant; La Salle; Avoyelles; Morehouse; Ouachita; Caldwell; Richland; Catahoula; Franklin; Concordia; Tensas; Madison; East Carroll; and West Carroll.</p><p>Regional representatives shall be elected at the annual LCA membership meeting for one-year terms. All LCA members in the region in question shall be eligible to vote for the regional representative. If no LCA member of a region is present at the LCA meeting, the membership of the LCA as a whole may select a provisional regional representative. If the provisional regional representative wishes to serve on the Board of Directors, he shall be the regional representative. If he does not, the other members shall select a resident of the region to serve as regional representative until the next election.<br><br></p><p>3. Decisions by the Board of Directors shall be made by majority vote unless otherwise provided by these by-laws or rules passed by the membership. The President shall chair the Board of Directors.<br><br></p><p>4. If a vacancy should occur on the Board of Directors between elections, the President shall appoint a replacement with the consent and approval of the Board.<br><br></p><p>5. The membership or the Board of Directors may appoint an LCA member to be in charge of preparing LCA Bulletins. The membership or the Board of Directors may appoint an LCA member to be in charge of maintaining a website for the LCA. These positions are not positions on the Board of Directors, but may be filled by LCA members that are on the Board of Directors.<br><br><br></p><p>Article IV: By-Laws, Rules, and Directives</p><p>1. There shall be three types of regulations governing the LCA: By-laws, Rules, and Directives. By-laws are regulations set forth in this document and by amendment as set forth in this article. Rules are regulations passed by a majority vote of voting members of the LCA at LCA membership meetings. Directives are regulations passed by a majority vote of the Board of Directors.<br><br></p><p>2. By-laws are the highest form of regulation of the LCA. Rules are the second highest form of regulation of the LCA. Directives are the third highest form of regulation of the LCA. In the case of conflict, by-laws are controlling over rules and directives, and rules are controlling over directives.<br><br></p><p>3. The by-laws may be amended by having the amendment passed by the Board of Directors, published in two LCA Bulletins or posted on the LCA Website for three months prior to submission to the membership, and passed by a two-thirds majority of the voting members present at an LCA membership meeting.<br><br><br></p><p>Article V: Duties of the Officers and the Board of Directors<br><br></p><p>1. President</p><p>a. Preside at all meetings of the membership and the Board of Directors.</p><p>b. Assign duties to the members of the Board of Directors.</p><p>c. Organize the competition to determine the State Chess Champion of Louisiana or award the authority to organize the competition to someone else.<br><br></p><p>2. Vice-President</p><p>a. Preside over meetings of the membership and the Board of Directors in the absence of the President.</p><p>b. Supervise all LCA elections.</p><p>c. Be the coordinator between the LCA and chess clubs within Louisiana.<br><br></p><p>3. Secretary-Treasurer</p><p>a. Keep minutes of all membership meetings.</p><p>b. Keep records of membership.</p><p>c. Keep records of all decisions of the Board of Directors.</p><p>d. Keep records of all funds and all business transactions of the LCA.</p><p>e. Be able to provide an itemized financial statement of the LCA at all times.</p><p>f. Choose and maintain a checking account for the LCA.</p><p>g. Write and sign checks for LCA expenses.<br><br></p><p>4. Scholastic Coordinator</p><p>a. Promote scholastic chess in Louisiana.</p><p>b. Chair the Scholastic Committee, which shall organize scholastic chess championships for Louisiana with or without the assistance of outside organizers.</p><p>c. Coordinate between the LCA and schools with chess teams or clubs in Louisiana.<br><br></p><p>5. Board of Directors</p><p>a. Supervise the affairs of the LCA between membership meetings.</p><p>b. Pass all necessary or worthwhile directives to promote and encourage chess in Louisiana as the Board of Directors sees fit.</p>');
INSERT INTO "governance_documents" ("id","category","title","filename","file_url","doc_date","year","created_at","content") VALUES('bae312a1a0124cc7','bylaws','2010 Amendments',NULL,NULL,'2010-09-01',NULL,'2026-07-16 05:45:27','<ul><li><p>The board is authorized to pay the website administrator for the LCA website $100 per quarter.</p></li></ul><p><br>Stipends for the 2011 Denker &amp; Polgar Tournament of Champions reps and the La. USCF Delegate are set at $200.</p>');
INSERT INTO "governance_documents" ("id","category","title","filename","file_url","doc_date","year","created_at","content") VALUES('f39f527d12934a2d','bylaws','2011 Amendments',NULL,NULL,'2011-09-01',NULL,'2026-07-16 05:47:01','<ul><li><p>Beginning at the 2012 State Championship, LCA dues are set at $20 for adults and $10 for scholastic players.</p></li></ul><p><br>Stipends for the 2012 Denker &amp; Polgar Tournament of Champions reps are set at $200.<br><br>The board is authorized to continue paying the website administrator for the LCA website $100 per quarter.</p>');
INSERT INTO "governance_documents" ("id","category","title","filename","file_url","doc_date","year","created_at","content") VALUES('c24338c9042a42dd','bylaws','2012 Amendments',NULL,NULL,'2012-09-01',NULL,'2026-07-16 05:47:43','<ul><li><p>The state championship is to be&nbsp; held annually over on Labor Day weekend with the back-up date of Thanksgiving weekend in case of tropical weather.</p></li></ul><p><br>LCA membership is not required for students to play in the state scholastic championship.<br><br>LCA membership is required for all players, including students of any age, to play in non-scholastic LCA sanctioned tournaments.</p>');
INSERT INTO "governance_documents" ("id","category","title","filename","file_url","doc_date","year","created_at","content") VALUES('437ce792dd9e4e0b','bylaws','2013 Amendments',NULL,NULL,'2013-09-01',NULL,'2026-07-16 05:48:19','<ul><li><p>The annual LCA membership dues were set at $25 family (1 adult &amp; all children in a household), $15 adult, and $5 scholastic.</p></li></ul><p></p>');
INSERT INTO "governance_documents" ("id","category","title","filename","file_url","doc_date","year","created_at","content") VALUES('0c073250f1a14869','bylaws','2014 Amendments',NULL,NULL,'2014-09-01',NULL,'2026-07-16 05:48:35','<ul><li><p>No out-of-state players, including Masters, shall be offered free entry to any Louisiana State Championship Tournament.</p></li></ul><p></p>');
INSERT INTO "governance_documents" ("id","category","title","filename","file_url","doc_date","year","created_at","content") VALUES('2112898820944ff9','bylaws','2015 Amendments',NULL,NULL,'2015-09-01',NULL,'2026-07-16 05:48:47','<ul><li><p>The LCA Board is authorized to spend up to $1000 over the coming year to promote chess in Louisiana.</p></li></ul><p></p>');
INSERT INTO "governance_documents" ("id","category","title","filename","file_url","doc_date","year","created_at","content") VALUES('9535e722ed424f85','bylaws','2016 Amendments',NULL,NULL,'2016-09-01',NULL,'2026-07-16 05:49:00','<ul><li><p>The LCA Board is authorized to spend up to $1000 over the coming year to promote chess in Louisiana.</p></li></ul><p></p>');
INSERT INTO "governance_documents" ("id","category","title","filename","file_url","doc_date","year","created_at","content") VALUES('2a0b6270b95e4bd1','bylaws','2017 Amendments',NULL,NULL,'2017-09-01',NULL,'2026-07-16 05:49:34','<ul><li><p>The LCA Board is authorized to make donations totaling up to $1000 over the coming year to chess clubs in Louisiana that have lost equipment or assets in hurricanes.</p></li></ul><p><br>Adam Caveney is named a lifetime member of the LCA.</p>');
INSERT INTO "governance_documents" ("id","category","title","filename","file_url","doc_date","year","created_at","content") VALUES('712602d6f1704082','bylaws','2018 Amendments',NULL,NULL,'2018-09-01',NULL,'2026-07-16 05:51:03','<ul><li><p>The LCA Board shall meet either in person, via conference call, or via videoconference at least 5 times per year in addition to the annual membership membership meeting.</p></li></ul><p><br>The Vice President’s primary responsibility is to take over as President in the event that the President resigns or can no longer serve out the term.</p>');
INSERT INTO "governance_documents" ("id","category","title","filename","file_url","doc_date","year","created_at","content") VALUES('5621d9cd9a204f32','treasurer','2014 LCA Treasurer''s Report',NULL,NULL,'2014-09-01',NULL,'2026-07-16 05:54:04','<p>Beginning Balance: $3113.63</p><p><br>Income:</p><p>2013 State Championship &amp; Memberships: $571.16</p><p>Memberships from TSP Events: $420.00</p><p>Donation Made at 2013 State Championship: $400.00</p><p>Scholastic Championship Stipend Payment: $414.00</p><p>Extra Memberships Mailed In: $60.00</p><p>Total Income: $1865.16<br><br></p><p>Expenses:</p><p>USCF Affiliate Membership: $40.00</p><p>TSP Tournaments Net Loss: $155.22</p><p>Web Hosting Fee (Domain Name): $9.95</p><p>Scholastic Stipends: $400.00</p><p>Bulletin #1: $148.64</p><p>Bulletin #2: $219.42</p><p>Donation to Susan Polgar Foundation $300.00</p><p>Total Expenses: $1273.23<br><br></p><p>Beginning Balance: $3113.63</p><p>Plus Income: $1865.16</p><p>Less Expenses: $1273.23</p><p><br></p><p>Ending Balance: $3705.56</p>');
