INSERT INTO "governance_documents" ("id","category","title","filename","file_url","doc_date","year","created_at","content") VALUES('53d4b68158f9452c','treasurer','2023 LCA Treasurer''s Report',NULL,NULL,'2023-09-03',NULL,'2026-07-16 06:03:35','<p>LOUISIANA CHESS ASSOCIATION</p><p>TREASURER’S REPORT</p><p>September 3, 2023<br><br></p><p>September 5, 2022 Opening Balances Checking $3984.74</p><p>Venmo 435.00</p><p>Less: Unpaid 2021 Tmt of Champions Stipends (2000.00)</p><p>Beginning balance $2419.74<br><br></p><p>2022 State Championship: Dues paid by organizers 1135.00</p><p>Profit shared by organizers 42.22</p><p>Dues paid by members not playing 85.00</p><p>Balance after State Championship $3681.96<br><br></p><p>Income through year: Scholastic Kickoff $1008.04</p><p>Pro-Am/MLK 184.10</p><p>Scholastic Championship 800.00</p><p>Tmt of Champ. Qualifier 500.00</p><p>Dues paid during year 75.00</p><p>Sales of donated merchandise 329.00</p><p>Donations 425.25</p><p>Expenditures: 2023 TOC Rep Stipends 2250.00<br><br></p><p>Web hosting</p><p>29.95</p><p>Web maintenance 400.00</p><p>US Chess Affiliate Dues 40.00<br><br>Balance before 2023 Championship $4283.40</p><p>LCA Treasurer’s Report May 30, 2021<br><br></p><p>Beginning Balance (8/31/19): $ 7,391.42</p><p><br>Income:</p><p>Net Profit from LiChess Scholastic Event: $ 8.35 2019</p><p>LCA dues collected at 2019 state championship: $ 810.00</p><p>Total Income: $ 818.35<br><br>Expenses:</p><p>2020 &amp; 2021 USCF Affiliate Fees $ 80.00</p><p>2019 LCA Tournament of Champions Steipends $ 1,800.00</p><p>Website Domain Renewal $ 20.00</p><p>Website Maintenante $ 300.00</p><p>Total Expenses: $ 2,200.00</p><p><br>Beginning Balance: $ 7,391.42</p><p>Plus Income: $ 818.35</p><p>Less Expenses: $ 2,200.00<br><br>Ending Balance: $ 6,009.77</p>');
INSERT INTO "governance_documents" ("id","category","title","filename","file_url","doc_date","year","created_at","content") VALUES('96c2cc17af024ac1','minutes','LCA Meeting Minutes 2010',NULL,NULL,'2010-09-01',NULL,'2026-07-16 06:05:16','<p>I. The meeting was called to order by Secretary/Treasurer Adam Caveney.<br><br></p><p>II. President Sid Souvey presented an introductory address.<br><br></p><p>III. Secretary/Treasurer Caveney presented the 2009-2010 Treasurer’s report. For privacy</p><p>reasons, this report is not available online, but it can be obtained by any LCA member from Caveney</p><p>upon request. In general, the past year was good for the treasury and we have about $400 more in the</p><p>treasury this year than we did last year.<br><br></p><p>IV. The report from Louisiana USCF Delegate Patrick Hardy was presented. The report contained</p><p>an explanation of the major events that occurred at the USCF delegate’s meeting in California. Details</p><p>can be obtained from Hardy by LCA members upon request.<br><br></p><p>V. In the absence of the outgoing Scholastic Coordinator, R.J. Tagorda gave a report on the state</p><p>of scholastic chess in Louisiana. In general, while there were a few problems with the scholastic state</p><p>championship, scholastic chess in Louisiana was very strong in the past year, with many Louisiana</p><p>students performing well at national competitions.<br><br></p><p>VI. Elections for 2010-2011 LCA Officers and Board Members were held. Showing a general</p><p>consensus, all of the following officers and board members were elected unopposed:<br><br></p><p>President: Sid Souvey<br>Vice-President: Bob Ballard<br>Sec./Treas.: Adam Caveney<br>Scholastic Coordinator: R.J. Tagorda<br>New Orleans Area Board Rep.: Jules LeBon<br>Baton Rouge Area Board Rep.: Michael Crochet<br>Lafayette Area Board Rep.: Jim MacManus<br>North Louisiana Board Rep.: Matthew Ussery</p><p>Lake Charles Area Board Rep.: Vacant (No Lake Charles area members were in attendandce).</p><p><br><br>VII. It was explained that the Louisiana Delegate to the USCF and the alternate delegate were now</p><p>being selected by the LCA instead of directly elected by Louisiana USCF members. (This was a USCF rule</p><p>change.) The board then discussed whether the LCA should continue to provide a stipend to the USCF</p><p>delegate to help defer expenses of attending the USCF delegates meeting. A motion was proposed to</p><p>bar the LCA from providing any stipend on the theory that all positions in the LCA were voluntary. That</p><p>motion failed. A second motion was proposed providing for a $200 stipend for the USCF delegate for</p><p>the 2011 delegate’s meeting. That motion passed. The delegate election was then held. Patrick Hardy</p><p>was elected the USCF delegate unopposed. Jim MacManus was elected alternate delegate unopposed.</p><p><br><br>VIII. President Sid Souvey announced that the deadline for submitting bids for holding the 2011 State</p><p>Championship would be due on February 1, 2011.</p><p><br><br>IX. The possibility of holding tournaments in the Baton Rouge area now that former LCA President</p><p>Alex Steger has moved to Tennessee was discussed. Michael Crochet, Board Representative for the</p><p>Baton Rouge area stated that he might be able to hold tournaments in Baton Rouge.</p><p><br><br>X. It was reported that the LCA had received a $400 donation from Cajun Chess to pay someone</p><p>$100 per quarter to keep the LCA website updated. At the time of the meeting, $200 (two quarters) had</p><p>been paid to former website administrator Alex Steger. A motion was made to continue paying a</p><p>website administrator $100 per quarter when the donation money had been exhausted. The motion</p><p>passed.</p><p><br><br>XI. Given Alex Steger’s move to Tennessee, the membership then discussed who should be</p><p>appointed/elected the new website administrator. Patrick Ballard was selected as the new website</p><p>administrator unopposed. North Louisiana Board Rep. Matthew Ussery also stated that he act as</p><p>website administrator if necessary.</p><p><br><br>XII. Newly elected Scholastic Coordinator R.J. Tagorda led a discussion of scholastic issues. It was</p><p>announced that whoever was awarded the authority to hold the state scholastic championship would</p><p>have to have the flyer for that event (including the prize divisions and numbers of prizes) pre-approved</p><p>by the scholastic coordinator and a committed that would be appointed to set a standard format for the</p><p>state scholastic championship. It was also established that Tagora, as scholastic coordinator had the</p><p>authority to set a date for bids for scholastic state championship. Tagorda stated that the deadline</p><p>would be sometime this fall.</p><p><br><br>XIII. There was further discussion about the state championship in future years. The discussion did</p><p>not result in any motions being proposed or passed.</p><p><br><br>XIV. Jim Rousselle made a comment that he was impressed with the fighting chess he had seen at</p><p>this year’s state championship. A rare bout of modesty from the secretary prevents the person who was</p><p>the focus of Rousselle’s comment from being reported in the minutes.</p><p><br><br>XV. The meeting was adjourned.</p>');
INSERT INTO "governance_documents" ("id","category","title","filename","file_url","doc_date","year","created_at","content") VALUES('97ce0837f9fe4096','minutes','LCA Meeting Minutes 2011',NULL,NULL,'2011-09-01',NULL,'2026-07-16 06:09:31','<p>The meeting was called to order by Secretary/Treasurer Adam Caveney.</p><p><br></p><p>President Sid Souvey presented an introductory address.</p><p><br></p><p>Secretary/Treasurer Caveney presented the 2010-2011 Treasurer’s report. For privacy reasons, this report is not available online, but it can be obtained by any LCA member from Caveney upon request. In general, the past year was good for the treasury, but unfortunately Tropical Storm Lee depressed turnout at the 2011 to the point that the LCA lost a significant amount of money and the treasury is in serious trouble.</p><p><br></p><p>Scholastic Coordinator R.J. Tagorda gave a report on the state of scholastic chess in Louisiana. In general, scholastic chess in Louisiana was very strong in the past year, with many Louisiana students performing well at national competitions. While Louisiana champions did not perform particularly well at national competitions of state champions, the future is in good shape as Louisiana players and teams did very well at open national events, with Tagorda reporting that Louisiana was probably now the fourth strongest scholastic state behind only much larger New York, California, and Texas.</p><p><br></p><p>In old business, the membership agreed to offer the standard stipend of $200 to Louiusiana’s Denker and Polgar representatives. The membership agreed not to pay the previously passed stipend to the Louisiana USCF Delegate as he had requested it not to be paid because he could not attend the USCF Delegates meeting due to illness.</p><p><br></p><p>Elections for 2010-2011 LCA Officers, Board Members, and USCF Delegate and Alternate Delegate were held. Showing a general consensus, all of the following officers and board members were elected unopposed:</p><p><br><br></p><p>President: Sid Souvey</p><p><br></p><p>Vice-President: Bob Ballard</p><p><br></p><p>Sec./Treas.: Adam Caveney</p><p><br></p><p>Scholastic Coordinator: R.J. Tagorda</p><p><br></p><p>New Orleans Area Board Rep.: Jules LeBon</p><p><br></p><p>Baton Rouge Area Board Rep.: J. Eryk Hargrove</p><p><br></p><p>Lafayette Area Board Rep.: Jim MacManus</p><p><br></p><p>North Louisiana Board Rep.: Matthew Ussery (appointed in absentia)</p><p><br></p><p>Lake Charles Area Board Rep.: Fred Boerman</p><p><br></p><p>USCF Delegate: Patrick Hardy</p><p><br></p><p>USCF Alternate Delegate: Mario Rodriguez</p><p><br></p><p>It was reported that the LCA had received a $400 donation to pay someone $100 per quarter to keep the LCA website updated for the next year. A motion was made to continue paying a website administrator $100 per quarter when the donation money had been exhausted. The motion passed. A motion was presented to continue Patrick Ballard as the website administrator. The motion passed.</p><p><br></p><p>Due to the financial problems of the LCA due to Tropical Storm Lee causing the state championship to lose a significant amount of money, a motion was raised to suspend all stipend payments to both state scholastic representatives and USCF Delegates until the treasury had $5,000 in it. The motion included a provision that the Board could approve a stipend to a state scholastic representative in the case of hardship. The motion passed after much discussion.</p><p><br></p><p>It was proposed that the State Championship be moved to Memorial Day Weekend to avoid tropical weather. It was noted, however, that it was unclear whether hotel space was available at reasonable prices in New Orleans at that time, and it was also noted that the State Championship has been held on Labor Day Weekend for a long time. Given the lack of attendance at the meeting, it was agreed that the issue would be tabled for discussion next year when knowledge of the hotel space could be obtained and more members were present.</p><p><br></p><p>It was proposed that Louisiana’s State Champion be awarded through a closed championship rather than the current open championship format. The issue was discussed and while the membership was receptive to the idea of a closed championship, the membership was not particularly in favor of selecting the official state champion in this manner. The issue was tabled for further discussion next year.</p><p><br></p><p>It was proposed that the LCA run a City Championship in Baton Rouge to revive chess in that city as Baton Rouge chess has fallen off recently. It was noted that there is a relatively cheap site to hold a tournament there, at least in a one-day format. It was also noted that anyone wishing to hold such a tournament could hold such a tournament under the current rules as a TSP tournament. No motions were made or passed on the issue.</p><p><br></p><p>Due to the fact that LCA dues have not been increased in over 20 years and the financial troubles of the LCA, it was proposed that LCA dues be increased. After much discussion, and over significant opposition, the membership voted to raised dues to $20 for adults and $10 for scholastic players, effective starting at next year’s state championship. The hold in raising the dues was made to allow the membership, if more show up at next year’s meeting, to vote to change the dues back at that time and refund any excess dues paid at next year’s state championship. It was also hoped that more people might show up at next year’s meeting if there was opposition to the dues increase.</p><p><br></p><p>The meeting was adjourned.</p>');
INSERT INTO "governance_documents" ("id","category","title","filename","file_url","doc_date","year","created_at","content") VALUES('378c7a9e95664a39','minutes','LCA Meeting Minutes 2012',NULL,NULL,'2012-09-01',NULL,'2026-07-16 06:11:52','<p>I. The meeting was called to order by Secretary/Treasurer Adam Caveney.</p><p><br>II. President Sid Souvey presented an introductory address.<br><br>III. Secretary/Treasurer Caveney presented the 2011-2012 Treasurer’s report. For privacy</p><p>reasons, this report is not available online, but it can be obtained by any LCA member from Caveney</p><p>upon request. In general, the past year was not good for the treasury because Tropical Storm Lee</p><p>depressed turnout at the 2011 to the point that the LCA lost a significant amount of money. On the</p><p>positive side, the LCA did well at the TSP events, the Pro-Am and the Paul Morphy Open.<br><br>IV. Scholastic Coordinator R.J. Tagorda gave a report on the state of scholastic chess in Louisiana.</p><p>In general, scholastic chess in Louisiana was strong on quality, but short on quantity. Louisiana</p><p>scholastic players continued to do well in national competitions, including Dex Webster being the</p><p>National 5th Grade Champion. However, the lack of coaches in Louisiana available to coach at schools</p><p>limited the number of schools participating in chess.</p><p><br>V. In old business, the issue of membership dues was revived after due were raised last year to</p><p>$20 for adults and $10 for scholastic players. Caveney presented a proposed LCA Fiscal Sustainability</p><p>Plan that involved all memberships being $15 among other things. Voting was tabled until new business</p><p>because some members did not want to vote on dues until services provided by the LCA were discussed.</p><p>In other old business, the weekend for the state championship was discussed. By acclamation, players</p><p>wanted to retain the seven-round format. That generally allowed only three weekends: Memorial Day,</p><p>Labor Day, and Thanksgiving. Eryk Hargrove suggested a two-day seven-round format with the first four</p><p>rounds being G/1. That suggestion did not gain much support. Each three-day weekend had problems:</p><p>scholastic players do not all get Memorial Day off and are often in exams at that time; Labor Day</p><p>Weekend is at the height of hurricane season; and Thanksgiving Weekend is a major family holiday with</p><p>many people out of town. After much discussion, by a significant majority, the membership voted to</p><p>keep the tournament on Labor Day with Thanksgiving Weekend being the back-up plan in case of</p><p>tropical weather on Labor Day. The final matter of old business was whether to select the Louisiana</p><p>State Champion in a closed, invitational format rather than the current open format. The suggestion</p><p>failed more or less by acclamation.</p><p><br>VI. Elections for 2012-2012 LCA Officers, Board Members, and USCF Delegate and Alternate</p><p>Delegate were held. Showing a general consensus, all of the following officers and board members were</p><p>elected unopposed:</p><p>President: James Rouselle</p><p>Vice-President: Bob Ballard</p><p>Sec./Treas.: Adam Caveney</p><p>Scholastic Coordinator: R.J. Tagorda</p><p>New Orleans Area Board Rep.: Sid Souvey</p><p>Baton Rouge Area Board Rep.: Stuart Collins</p><p>Lafayette Area Board Rep.: Jim MacManus</p><p>North Louisiana Board Rep.: Vacant (will be filled by Presidential appointment)</p><p>Lake Charles Area Board Rep.: Vacant (will be filled by Presidential appointment)</p><p>USCF Delegate: Mario Rodriguez</p><p>USCF Alternate Delegate: Leila D’Aquin</p><p><br>VII. During new business, it was announced that Patrick Ballard had agreed to continue to be the</p><p>LCA website administrator and without compensation for the forthcoming year. The motion to</p><p>reappoint Patrick Ballard as LCA website administrator was passed by acclamation. Patrick Ballard was</p><p>awarded a free LCA membership for the upcoming year by acclamation.<br><br>VIII. The LCA Fiscal Sustainability Plan (FSP) was considered in conjunction with another proposal by</p><p>Caveney, the LCA Website Improvement Plan (WIP). After much discussion and amendment of both</p><p>proposals, both were passed as amended. Dues remained at $20 for adults and $10 for scholastic</p><p>players. LCA membership no longer required for state scholastic championship. LCA membership now</p><p>required for all players in LCA membership required adult tournaments, whereas previously players in</p><p>8th grade or lower were not required to get LCA memberships. Both the FSP and WIP, as amended and</p><p>passed, are available on the LCA website.<br><br>IX. Outgoing President Sid Souvey expressed concern about the lack of details presented in bids</p><p>for the state championship. It was pointed out that nobody had actually made a formal bid for the state</p><p>championship in many years and the LCA basically had to ask people or chess clubs to hold it. No</p><p>motions were made or passed on this issue.</p><p><br>X. The meeting was adjourned.</p>');
INSERT INTO "governance_documents" ("id","category","title","filename","file_url","doc_date","year","created_at","content") VALUES('0a0baac577464e4d','minutes','LCA Meeting Minutes 2013',NULL,NULL,'2013-09-01',NULL,'2026-07-16 06:13:56','<p>1. Call to Order</p><p>The meeting was called to order.</p><p><br>2. President’s Address</p><p>LCA President James Rousselle gave a brief overview of LCA activity</p><p>during 2012-13 and plans for the future.</p><p><br>3. Treasurer’s Report</p><p>LCA Secretary/Treasurer Adam Caveney gave the Treasurer’s Report. This</p><p>report is written and available on the website separately.</p><p><br>4. Scholastic Coordinator Report</p><p>As outgoing Scholastic Coordinator R.J. Tagorda had moved to Oregon,</p><p>Leila D’Aquin gave an address regarding scholastic chess in Louisiana and the</p><p>USCF Delegates Meeting. Most of the information regarding scholastic chess was</p><p>included in an article in the most recent LCA Bulletin (Fall-Winter 2013). The</p><p>information regarding the delegates meeting was interesting and your humble and</p><p>quite unqualified secretary failed to take sufficient notes to even attempt to give a</p><p>summary.</p><p><br>5. Old Business: Proposed LCA By-Laws Amendment</p><p>Old By-Law: The by-laws may be amended by having the amendment passed</p><p>by the Board of Directors, published in two LCA Bulletins prior to submission to</p><p>the membership, and passed by a two-thirds majority of the voting members present</p><p>at an LCA membership meeting.</p><p>Proposed New By-Law (changes in bold): The by-laws may be amended by having</p><p>the amendment passed by the Board of Directors, published in two LCA Bulletins</p><p>or posted on the LCA Website for three months prior to submission to the</p><p>membership, and passed by a two-thirds majority of the voting members present at</p><p>an LCA membership meeting.</p><p>The proposed new By-Law passed unanimously.</p><p><br>6. Officer Elections:</p><p>Officer elections were held. All officers ran unopposed. There were no</p><p>LCA members from the Lake Charles or North Louisiana areas present, and those</p><p>offices remain vacant.</p><p>President: James Rousselle</p><p>Vice-President: Bob Ballard</p><p>Sec./Treas.: Adam Caveney</p><p>Scholastic Coordinator: Cheryl Webster</p><p>USCF Delegate: Leila D’Aquin</p><p>USCF Alternate Delegate: Michael Tisserand</p><p>New Orleans Area Board Rep.: Mitch Costanza</p><p>Baton Rouge Area Board Rep.: Stuart Collins</p><p>Lafayette Area Board Rep.: Jim MacManus</p><p>North Louisiana Board Rep.: Vacant</p><p>Lake Charles Area Board Rep.: Vacant</p><p><br>7. New Business:</p><p><br>A. Membership Dues/Request for Board to be authorized to spend money</p><p>to promote chess in Louisiana.</p><p><br>LCA President James Rousselle detailed plans for the upcoming year</p><p>including promoting chess through sending a bulletin to all USCF members in</p><p>Louisiana. It was suggested that the chess promotion efforts would cost</p><p>approximately $1,000. There did not seem to be significant opposition to the plan</p><p>and a vote was not technically necessary, so no vote was held.</p><p><br>The membership then considered the dues issue for the third year in a row.</p><p>By a unanimous vote, the membership chose to change the dues structure from the</p><p>present $20 adult/$10 scholastic. Two proposals were made. James Rousselle</p><p>proposed returning to the previous $10 adult/$5 scholastic membership structure.</p><p>After much discussion and interim proposals, Leila D’Aquin proposed the</p><p>following membership structure: $25 family/$15 adult/$5 scholastic. It was</p><p>decided that the new change would also involve not requiring LCA membership</p><p>for the state scholastic championship but requiring it for all scholastic players</p><p>playing in adult tournaments that are LCA membership required where previously</p><p>only high school age and above were required. By an 18-7 vote, the dues structure</p><p>proposed by Leila D’Aquin ($25 family/$15 adult/$5 scholastic) was approved.</p><p><br>B. New Website/Website Administrator</p><p>LCA Website Administrator Patrick Ballard stated that he hoped that the</p><p>redesigned website would be launched by the end of the year.</p><p><br>C. Other Issues Raised By Membership/Officers</p><p>Leila D’Aquin announced that a new chess club playing quads would be</p><p>launched in October at Pantera Bread on Carrollton Avenue in New Orleans.</p><p><br>8. Adjournment</p><p>By unanimous vote, the meeting was adjourned.</p>');
INSERT INTO "governance_documents" ("id","category","title","filename","file_url","doc_date","year","created_at","content") VALUES('8f94a7032e394f24','minutes','LCA Meeting Minutes 2014',NULL,NULL,'2014-09-01',NULL,'2026-07-16 06:15:24','<p>1. Call to Order</p><p>The meeting was called to order.</p><p><br>2. President’s Address</p><p>LCA President James Rousselle gave a brief address. He apologized for not playing in</p><p>the State Championship due to illness. He thanked the board members for their work</p><p>over the past year and warned any possible new board members that he would put</p><p>them to work. He also commended the good turnout at the State Championship.</p><p><br>3. Treasurer’s Report</p><p>Secretary/Treasurer Adam Caveney presented the annual Treasurer’s Report. That</p><p>document is available separately on the website.</p><p><br>4. Louisiana USCF Delegate Report</p><p>Louisiana USCF Delegate Leila D’Aquin gave a summary of the USCF annual meetings</p><p>held at the U.S. Open, and noted the following items:</p><p><br>A. The USCF has finally been approved for § 501(c)(3) status as a charity. This will</p><p>allow more chess promotion and possibly grants for USCF memberships for scholastic</p><p>players.</p><p><br>B. The USCF membership, after being in decline for several years, has been rising</p><p>since 2011. Louisiana is one of the fastest growing states, with an increase of 10% in</p><p>USCF members since 2011.</p><p><br>C. USCF goals for the upcoming years include increasing scholastic members and girls</p><p>and women, especially after college age. A new video has been produced to encourage</p><p>chess for all girls schools.</p><p><br>D. New USCF Executive Director Jean Hoffman seeks to increase scholastic affiliates</p><p>by 20%. Part of the incentive for affiliate membership will be to allow schools to buy a</p><p>block of USCF memberships for students at a discount.</p><p><br>E. The USCF will strive to achieve consistency in scholastic ratings. Areas are currently</p><p>allowed to use alternative rating systems, but this led to a team from the Pacific</p><p>Northwest all being allowed to compete in the Under 600 section at nationals, where</p><p>they all won all of their games, leading to belief that they really should not have been</p><p>under 600.</p><p><br>F. Effective January 1, 2015, the USCF will make castling a king move, meaning</p><p>castling is not allowed if a player touches the rook first. The move is made to make</p><p>USCF rules consistent with FIDE rules.</p><p><br>G. The new USCF Rulebook is now official and available.</p><p><br>5. Scholastic Coordinator’s Report</p><p>Scholastic Coordinator Cheryl Webster gave her report. The main points were the</p><p>following.</p><p><br>A. Lots of teams are now participating with 47 teams from 16 different schools</p><p>competing at the scholastic state championship.</p><p><br>B. The Susan Polgar New Orleans tournament was a success with over 150 scholastic</p><p>players from 18 different states.</p><p><br>C. Louisiana sent many players to the national scholastic tournaments with 15 students</p><p>at the elementary tournament, 9 at the junior high tournament, and 1 at the high school</p><p>tournament.</p><p></p><p>D. The second tournament run by the Foundation for East Baton Rouge Parish had</p><p>about 120 students. The third tournament will be held September 6, 2014.</p><p></p><p>E. A new system of charter schools, the Solarity Charter Schools, with three schools in</p><p>Baton Rouge and one in Harvey, has chess as part of the school curriculum.</p><p><br>6. Board Member Reports</p><p>A. Stuart Collins (Baton Rouge):</p><p>Stuart Collins reported that the Baton Rouge Chess Club is again playing rated chess.</p><p>They play at 10 AM on Saturday mornings at the main library. There is no entry fee or</p><p>prizes. The tournaments tend to be small, with about 12 players, but very strong.</p><p><br>7. Officer Elections:</p><p>Officer elections were held for the upcoming years. All ran unopposed. There were no</p><p>players from North Louisiana or Lake Charles. The Lake Charles board position remains</p><p>vacant. Ken Wyzywany was appointed the North Louisiana board member in absentia</p><p>without dissent.</p><p>President: James Rousselle</p><p>Vice-President: Bob Ballard</p><p>Sec./Treas.: Adam Caveney</p><p>Scholastic Coordinator: Cheryl Webster</p><p>USCF Delegate: Leila D’Aquin</p><p>USCF Alternate Delegate: Eli Karp</p><p>New Orleans Area Board Rep.: Mitch Costanza</p><p>Baton Rouge Area Board Rep.: Stuart Collins</p><p>Lafayette Area Board Rep.: Tommy LeBlanc</p><p>North Louisiana Board Rep.: Ken Wyzywany (appointed)</p><p>Lake Charles Area Board Rep.: Vacant</p><p><br>8. New Business:</p><p><br>A free lifetime family membership for an anonymous donor who has contributed</p><p>generously to the LCA for many years was passed unanimously.</p><p><br>President James Rousselle stated that he planned to introduce the FIDE time control of</p><p>G/90 with 30 second increment in future state championships with the goal of getting</p><p>tournaments FIDE rated and more players with FIDE ratings in the state. He stated that</p><p>he would encourage tournament organizers of other tournaments to do the same. There</p><p>was not significant dissent. Sec/Treas Adam Caveney, who runs two of the bigger</p><p>tournaments in Louisiana each year was on board with the idea although he worried he</p><p>would be perpetually in time trouble for hours in all games.</p><p><br>Two members raised objections to out-of-state masters receiving free entries into</p><p>tournaments with the entry fee taken out of any prize won, thinking that all players</p><p>should be treated equally. It was noted that for state championships, Louisiana masters</p><p>could not receive the same benefit because of a by-law provision prohibiting any</p><p>Louisiana player from gaining any advantage at state championship. It was also noted</p><p>that for tournaments other than the state championship, this was an organizer’s</p><p>decision, not the decision of the LCA, so the issue was whether to prohibit the practice</p><p>at future state championships. A vote was held, and the membership voted</p><p>overwhelmingly, but not unanimously to prohibit the practice at future state</p><p>championships. An objection was made to procedure, requesting more discussion and</p><p>the matter was reopened. Scholastic Coordinator Cheryl Webster noted that the LCA</p><p>was contradicting itself by encouraging FIDE time controls to get stronger players and</p><p>prohibiting this practice which does the same. Another vote was held. This time, the</p><p>prohibition was passed unanimously, but several members abstained.</p><p><br>At this time, Secretary/Treasurer Caveney moved to adjourn the meeting. This proposal</p><p>passed unanimously.</p>');
INSERT INTO "governance_documents" ("id","category","title","filename","file_url","doc_date","year","created_at","content") VALUES('dc2e919cbebe4b25','minutes','LCA Meeting Minutes 2015',NULL,NULL,'2015-09-01',NULL,'2026-07-16 06:17:50','<p>1. Call to Order</p><p>The meeting was called to order. It was agreed that LCA members who had not yet</p><p>paid, but were paying at the tournament could participate.</p><p><br>2. President’s Address</p><p>LCA President James Rousselle gave a brief address. He asked for (and received) a</p><p>moment of silence for Jim MacManus, the longtime Louisiana chess player and LCA</p><p>board member who recently passed away. He thanked the hotel for the parking</p><p>management that made the tight squeeze in the lot very easy. He noted that the state</p><p>championship was FIDE rated. He announced that Cajun Chess was bringing two</p><p>national events to Louisiana in 2016—the US Junior Open and US Senior Open, and</p><p>that they were bidding on a third, the Pam Am Intercollegiate Championships.</p><p><br>3. Treasurer’s Report</p><p>Secretary/Treasurer Adam Caveney presented the annual Treasurer’s Report. That</p><p>document is available separately on the website.</p><p><br>4. Louisiana USCF Delegate Report</p><p>Louisiana USCF Delegate Leila D’Aquin gave a summary of the USCF annual meetings</p><p>held at the U.S. Open, and noted that it was a good meeting. Focus was on scholastic</p><p>chess as more than half of USCF members are now scholastic players; the median age</p><p>of USCF members is 10. It was reported that if a child plays in five rated events by the</p><p>age of 16, the child is much more likely to continue to be a USCF member as an adult.</p><p>She also noted an increasing USCF emphasis on serving the general public as well as</p><p>members because they had receive charitable tax status.</p><p><br>5. Scholastic Coordinator’s Report</p><p>It was reported that Scholastic Coordinator Cheryl Webster was stepping down and was</p><p>not present.</p><p><br>6. Board Member Reports</p><p>A. Stuart Collins (Baton Rouge):</p><p>Stuart Collins reported that the Baton Rouge Chess Club is still playing rated chess.</p><p>They play at 10 AM on Saturday mornings at the main library. There is no entry fee or</p><p>prizes. He noted that there was a new player from Pittsburgh who had also started a</p><p>chess club at a school.</p><p>Although Lafayette Board Member Tommy LeBlanc was not present, it was announced</p><p>that the Lafayette Open/Jim MacManus Memorial would be held on Oct. 17-18 in</p><p>Lafayette.</p><p><br>7. Officer Elections:</p><p>Officer elections were held for the upcoming years. All ran unopposed. There were no</p><p>players from North Louisiana or Lake Charles. The Lake Charles board position remains</p><p>vacant. Ken Wyzywany was appointed the North Louisiana board member in absentia</p><p>without dissent.</p><p>President: James Rousselle</p><p>Vice-President: Bob Ballard</p><p>Sec./Treas.: Adam Caveney</p><p>Scholastic Coordinator: Ken Ferguson</p><p>USCF Delegate: Leila D’Aquin</p><p>USCF Alternate Delegate: Mario Rodriguez</p><p>New Orleans Area Board Rep.: Mitch Costanza</p><p>Baton Rouge Area Board Rep.: Stuart Collins</p><p>Lafayette Area Board Rep.: Tommy LeBlanc</p><p>North Louisiana Board Rep.: Vacant (no one present)</p><p>Lake Charles Area Board Rep.: Vacant (no one present)</p><p><br>8. New Business:</p><p>President James Rousselle opened the discussion by asking what the membership</p><p>wanted to do eventually with the larger amounts of money in the treasury. Asked how</p><p>much was enough for the treasury? There was discussion of trying to bid for a national</p><p>tournament as the LCA (with or without participation from Cajun Chess). It was noted</p><p>that it would be a few years before we had that kind of money. It was suggested by a</p><p>new member that cities in the Northeast all had their own big city opens, maybe we</p><p>could. The New Orleans Open was noted as already existing. Members discussed</p><p>having an invitation for strong grandmasters. It was suggested that a committee be</p><p>appointed to investigate options and report back next year. Jean Troendle also reported</p><p>the upcoming Cajun Chess national events in New Orleans. She said that the bidding</p><p>for the Pan Am was between Cajun Chess and University of Maryland, Baltimore</p><p>County (UMBC). President Rousselle gave his story from attending the US Masters,</p><p>and commended on how nice the event was, but noted that it cost the organizers</p><p>$50,000. (We won’t ever have that kind of money.)</p><p><br>At this time, Secretary/Treasurer Caveney moved to adjourn the meeting. This proposal</p><p>passed by acclamation.</p>');
INSERT INTO "governance_documents" ("id","category","title","filename","file_url","doc_date","year","created_at","content") VALUES('b6cf53507d064cf9','minutes','LCA Meeting Minutes 2016',NULL,NULL,'2016-09-01',NULL,'2026-07-16 06:20:05','<p>1. Call to Order</p><p>The meeting was called to order.</p><p><br>2. President’s Address</p><p>President James Rousselle apologized for the second round of the tournament being</p><p>played during the LSU game. (Had he already known the result of that game, he might</p><p>not have done this.) President Rousselle noted that upon request from players, FIDE</p><p>rated events and national tournaments had been brought to Louisiana. He noted that he</p><p>wants more communication between those involved in Louisiana chess to avoid</p><p>conflicts and other issues. He suggested a monthly, short e-bulletin to help facilitate</p><p>communication. The need for a new bulletin editor was detailed. President Rousselle</p><p>concluded by announcing that a $25 upset prize for the tournament, counting only</p><p>games through the fifth round, the $25 being a gift certificate for use at Cajun Chess</p><p>book and equipment sales on the last day of the tournament.</p><p><br>3. Treasurer’s Report</p><p>Secretary/Treasurer Adam Caveney briefly presented the Treasurer’s Report. The</p><p>report is in writing separately.</p><p><br>4. Louisiana USCF Delegate Report</p><p>USCF Delegate Leila D’Aquin noted that her report was included in the previous</p><p>bulletin. She provided a few copies of the USCF Annual Report. She stated that two</p><p>proposals at the delegates meeting could affect Louisiana chess: a proposal that all</p><p>small states get at least two delegates (Louisiana currently has only one) and a</p><p>proposal that a tournament of senior state champions be included at the U.S. Open</p><p>along with the tournaments of high school, middle school (or younger), and girls state</p><p>champions.</p><p><br>5. Scholastic Coordinator’s Report</p><p><br>Scholastic Coordinator Ken Ferguson presented his report on scholastic chess from the</p><p>previous year. He noted that the Louisiana Scholastic Chess League (LSCL) ran as</p><p>usual this year and that teams from four different schools won the different grade</p><p>categories. Scholastic Coordinator Ferguson lamented that when there were disputes in</p><p>scholastic tournaments, those disputes tended to get belligerent quickly. He stated that</p><p>there were four issues during the LSCL and that three of them were not based in fact</p><p>and the fourth was resolved quickly.</p><p><br>At this point, Scholastic Coordinator Ferguson noted that there was a philosophical</p><p>movement within scholastic chess with which he did not agree: that we should try to get</p><p>all the scholastic players to play rated chess. He stated that he was glad that the LSCL</p><p>was not rated, and he opined that not all kids want to play rated chess; some just want</p><p>to have fun with their friends, usually players who played on boards 3-6 in team</p><p>tournaments. He noted that of 64 kids from two teams he coached four years ago, only</p><p>seven or eight of them still play chess. Scholastic Coordinator Ferguson asserted that</p><p>the schools that wanted everything to be rated tended to be the richer schools and that</p><p>some schools primarily had players who could not afford all the fees.</p><p><br>Scholastic Coordinator Ferguson stated that it was not realistic for Louisiana to be like</p><p>Texas, California, and Florida in scholastic chess matters. He opined that it was not a</p><p>good thing for Louisiana to try to do this because the ultra-intense environment of USCF</p><p>rated chess was not a good thing for everyone and that making everything rated was</p><p>not feasible. He opined that it was a mistake to try to force this issue as it would cause a</p><p>rift in Louisiana scholastic chess.</p><p><br>Rex Williams asked Scholastic Coordinator Ferguson how much local support was</p><p>received at the U.S. Junior Open that was held in New Orleans in June. Scholastic</p><p>Coordinator Ferguson noted that the support was small and that most of the schools</p><p>that had pushed for more rated chess had not sent any players to the U.S. Junior Open</p><p>(which was a rated event). Scholastic Coordinator Ferguson further noted that extra</p><p>tournaments had been added to the schedule at the last minute and that he only heard</p><p>about one 2.5 days before the tournament. He stated that more communication was</p><p>needed.</p><p><br>6. Board Member Reports</p><p><br>Given the length of the meeting to this point, no further board member reports were</p><p>given.</p><p><br>7. Old Business:</p><p><br>A. By-law Amendment Vote 1</p><p><br>The by-laws currently provide that all questions regarding whether a player is a</p><p>Louisiana resident shall be determined by the membership. This amendment clarified</p><p>that this requirement applied only to questions of state residency for the purposes of the</p><p>adult state championship when the membership meeting is held. The author of the</p><p>amendment, Secretary/Treasurer Adam Caveney explained that the amendment was</p><p>necessary because there had been a question of Louisiana residency involving a</p><p>scholastic player that almost required the calling of an emergency membership meeting</p><p>this summer. He explained that the original by-law requirement (which he also wrote)</p><p>was only intended to apply to the adult state championship and that he had only</p><p>included it in the by-law re-write in 2007 because of the issue that had occurred in 1992.</p><p>USCF Delegate Leila D’Aquin asked what had happened in 1992, forcing many</p><p>members to hear for the thousandth time why Secretary/Treasurer Caveney believes</p><p>that he was a state resident (and the rightful state champion) as a freshman at Tulane in</p><p>1992.</p><p><br>Subsequently, the amendment was passed by a unanimous vote of the membership.</p><p><br>B. By-law Amendment Vote 2</p><p><br>The second proposed by-law amendment modified the by-laws to provide that the</p><p>scholastic coordinator would chair the scholastic committee, thereby creating a</p><p>scholastic committee to run scholastic chess in Louisiana. The amendment’s author,</p><p>USCF Delegate Leila D’Aquin, presented an amendment and provided a different vision</p><p>for scholastic chess than the vision presented by Scholastic Coordinator Ken Ferguson</p><p>in his report. In favor of the amendment, USCF Delegate D’Aquin and others made the</p><p>following arguments: (1) more coordination is needed in scholastic chess and a</p><p>committee will help facilitate this; (2) more thorough scholastic rules, like other states</p><p>have, are needed, and a committee can help draft them; (3) a couple of years ago the</p><p>state scholastic championship was held in Baton Rouge at the same time as another</p><p>scholastic tournament in Baton Rouge and we need more communication to prevent</p><p>issues like this; (4) the LCA has a board but not all of the members are involved in</p><p>scholastic chess; scholastic chess needs its own board; and (5) at worst, the committee</p><p>would be advisory and do nothing, which would not be a change from the status quo.</p><p>Those opposed to the proposed by-law amendment made the following arguments: (1)</p><p>there is no need for a committee to be written into the by-laws, a scholastic coordinator</p><p>can take advice from whomever he or she wants; (2) committees are a mess; if you put</p><p>three or four different people in the mix, you get three or four different opinions; (3) a</p><p>committee authorized by the membership last year was never formed and never met;</p><p>and (4) to facilitate communication, the scholastic coordinator should stay in touch with</p><p>others in the scholastic chess community and vice versa.</p><p><br>During the discussion of this proposed amendment, it was noted that there was almost</p><p>certainly going to be a contested election for the scholastic coordinator position. It was</p><p>suggested that the vote on the amendment be tabled until the winner of that contested</p><p>election was known so that members would know whether the winner wanted the</p><p>committee or not. After initially continuing further discussion, the membership later</p><p>voted 20-2 to table consideration of this proposed amendment until new business, after</p><p>the elections.</p><p><br>8. Officer Elections:</p><p><br>Most of the officer elections went normally. President James Rousselle, Vice-President</p><p>Bob Ballard, and Secretary/Treasurer Adam Caveney were all re-elected without</p><p>opposition, as were USCF Delegate Leila D’Aquin and alternate USCF Delegate Mario</p><p>Rodriguez. Ronald Squires was elected New Orleans board representative without</p><p>opposition after being nominated by his predecessor Mitchell Constanza. Similarly,</p><p>Mark Morreale was elected Baton Rouge board representative without opposition after</p><p>being nominated by his predecessor Stuart Collins. Tommy LeBlanc was elected</p><p><br>Lafayette board representative in absentia; outgoing Lafayette board representative Ben</p><p>Bailey was ineligible to continue to serve in that capacity as he had moved to New</p><p>Orleans. As the only member from North Louisiana present, David Gaston nominated,</p><p>seconded, and unanimously reelected himself as North Louisiana board representative.</p><p>The Lake Charles board representative position remained vacant because there were</p><p>no Lake Charles residents present.</p><p>The race for the Scholastic Coordinator position, as expected, led to the first contested</p><p>LCA Election in a decade. What was unexpected, however, was that the race would be</p><p>a very competitive election with three good candidates. Rex Williams nominated</p><p>Scholastic Coordinator Ken Ferguson for reelection. USCF Delegate Leila D’Aquin</p><p>nominated Nick Matta. Someone I could not see nominated Michael Porcelli of Baton</p><p>Rouge. All three candidates teach chess at numerous schools and are well experienced</p><p>in the scholastic chess scene.</p><p><br>Matta stated that he supported the idea of a scholastic committee but thought that it</p><p>should be advisory. Ferguson noted that he was about to start teaching at his seventh</p><p>school, and he stated that he had worked with a broad array of parents, teachers, and</p><p>students, knowing the limits of what we can get out of all three. Porcelli stated that he</p><p>taught chess full-time for a charter school system in Baton Rouge. He asserted that</p><p>Louisiana could be like California or Texas in scholastic chess, and he stated that he</p><p>knew it would happen in Baton Rouge. He stated that he preferred having both rated</p><p>and non-rated sections at tournaments.</p><p><br>With no rules on how to handle a three-way election, the membership agreed that it</p><p>would be a run-off system between the top two finishers if nobody received a majority in</p><p>the first round. The first round was excruciating close: Matta led with 13 votes, and</p><p>Porcelli edged out Ferguson for second by a single vote—10-9. With no candidate</p><p>receiving anything close to a majority, a run-off election was held between Matta and</p><p>Porcelli. The first count of that vote was 14-14. The second count of the vote was 15-15.</p><p>(Note, this was not necessarily poor counting—some members abstained and then</p><p>voted to try to break the tie.) On the third count, Porcelli prevailed 17-15.</p><p><br>▪ President: James Rousselle</p><p>▪ Vice-President: Bob Ballard</p><p>▪ Sec./Treas.: Adam Caveney</p><p>▪ Scholastic Coordinator: Michael Porcelli</p><p>▪ USCF Delegate: Leila D’Aquin</p><p>▪ USCF Alternate Delegate: Mario Rodriguez</p><p>▪ New Orleans Area Board Rep.: Ronald Squires</p><p>▪ Baton Rouge Area Board Rep.: Mark Morreale</p><p>▪ Lafayette Area Board Rep.: Tommy LeBlanc</p><p>▪ North Louisiana Board Rep.: David Gaston</p><p>▪ Lake Charles Area Board Rep.: Vacant</p><p><br>9. New Business:</p><p>At this point, the meeting had already greatly exceeded its allotted time. The</p><p>membership quickly and unanimously passed the second proposed by-law amendment</p><p>on the recommendation of the new scholastic coordinator. The membership then, again</p><p>on the recommendation of the scholastic coordinator, passed a rule making the</p><p>committee advisory. President Rousselle then requested a renewal of a previous year’s</p><p>vote allowing the board to spend $1,000 to promote chess in Louisiana, and stated that</p><p>he wished to travel around the state to get everyone on the same page, especially in</p><p>regards to scholastic chess. The motion passed unanimously. The meeting was then</p><p>adjourned.</p>');
INSERT INTO "governance_documents" ("id","category","title","filename","file_url","doc_date","year","created_at","content") VALUES('b8c8d3c05b374bbb','minutes','LCA Meeting Minutes 2017',NULL,NULL,'2017-09-01',NULL,'2026-07-16 06:21:49','<p>1. Call to Order</p><p>The meeting was called to order by the Secretary/Treasurer at 2:10 PM.</p><p><br>2. President’s Address</p><p>President James Rousselle, noting that he was stepping down after five years at the</p><p>helm, thanked everyone for putting up with him for five years. He further thanked</p><p>Jean Troendle for bringing national events to Louisiana, both previously and the</p><p>upcoming 2018 National Senior and Junior Opens. Continuing the theme, he</p><p>thanked outgoing Secretary/Treasurer Adam Caveney for his contributions to</p><p>Louisiana Chess. Finally, he noted that there were too many people to thank for him</p><p>to mention them all, including tournament directors and those who ran chess clubs.</p><p><br>3. Treasurer’s Report</p><p>The Treasurer’s Report is posted separately. In sum, the LCA’s finances are good</p><p>and getting better. Caveney, noting his impending stepping down, thanked many</p><p>people, but notes were not taken of this because he was the one taking notes and has</p><p>no recollection of what he actually said. Your humble author assumes that it was</p><p>brilliant. ;)</p><p><br>4. Louisiana USCF Delegate Report</p><p>USCF Delegate Leila D’Aquin gave a long and detailed report. She noted that there</p><p>were more committed meetings and that there was a new USCF Executive Director</p><p>who has more experience with charitable organizations. She reported that the USCF</p><p>now had 501(k)(3) status for charitable work. Additionally, the clubs committee has</p><p>been reformulated and that the ratings committee is trying to maintain the bell curve</p><p>for all USCF ratings. She stated that the states’ committee is surveying state USCF</p><p>chapters (such as the LCA) to see what they are doing and want state chapters to</p><p>have more involvement in communities and with young people. She noted that the</p><p>USCF named the western Mississippi community of Folten (sp? I cannot read my</p><p>scribbles here, sorry) as the chess city of the year, even though it is not a</p><p>city. D’Aquin reported that the USCF now will have a tournament of state senior</p><p>champions that will be held with the U.S. Open, like the Denker (High School),</p><p>Barber (Middle School and below), and Girls’ (self-explanatory) tournaments</p><p>already are, and that in 2018, the tournaments will be in Madison, Wisconsin. She</p><p>noted that the USCF wanted more young delegates and that alternates can almost</p><p>always be seated because many delegates are no-shows. There was also something</p><p>else she said, but all I can make of my notes on this is “Eng’ &amp; St. touted snack,”</p><p>and I doubt that has anything to do with what was actually stated.</p><p><br>5. Scholastic Coordinator’s Report</p><p>Outgoing Scholastic Coordinator Michael Porcelli reported that the state scholastic</p><p>championship had far more participants than it had in recent years---</p><p>186. Additionally, the LCA held its first girls’ championship this year. It was also</p><p>announced that there was a new LCA scholastic website that has been</p><p>established. Additionally, there were more schools participating in chess and the</p><p>New Orleans Parks Department was adding more chess for next year. Porcelli</p><p>announced goals as having more rated events and more scholastic events throughout</p><p>the state next year. The committee that was established last year to get feedback</p><p>from parents and coaches, however, got no responses from parents and coaches, so</p><p>Porcelli worked with Troendle, Nick Matta, and D’Aquin to expand scholastic chess.</p><p><br>6. Board Member Reports</p><p>There were no further individual board member reports.</p><p><br>7. Old Business:</p><p>A. Call for Volunteers: Board Positions, Bulletin, Tournament Organizers.</p><p>With Caveney stepping down from chess organizational activities and no bulletin</p><p>editor in place, there was a call for volunteers to take over as bulletin editor and to</p><p>organize the Pro-Am and Morphy tournaments. Matta volunteered for bulletin</p><p>editor duties, and Porcelli expressed interest in running the tournaments.</p><p><br>8. Officer Elections:</p><p><br>For the second time in as many years (and the first for almost a decade) there were</p><p>contested elections. For the second time in as many years, there was no clear</p><p>result. For president, with Rousselle stepping down, both Porcelli and outgoing</p><p>Vice-President Bob Ballard were nominated and accepted the nominations. Porcelli</p><p>stated that he wanted to tour the state and run tournaments to get rated chess to the</p><p>whole state instead of just the I-10/I-12 corridor where it is usually confined. He</p><p>further stated that he wanted to get more people to be tournament directors to</p><p>facilitate more rated chess throughout the state. Ballard noted that he has been a</p><p>tournament director in Louisiana for 30 years, and he presented himself as a safe</p><p>option to continue the positive progress of the LCA in recent years. As per the usual</p><p>custom, the candidates were asked to wait outside while the vote occurred. There</p><p>were 26 LCA members who voted, and the result was a 13-13 tie. After a brief</p><p>discussion, the membership unanimously agreed to ask the candidates if they would</p><p>agree to be co-Presidents. The candidates accepted, and we now have co-Presidents.</p><p><br>There was also a contested election for New Orleans Area Board</p><p>Representative. Per a previous agreement, both Rousselle and Caveney nominated</p><p>each other and accepted. Incumbent Ronald Squires and someone whose name starts</p><p>with an “M” (Mitch Costanza?) were also nominated. (I really never should have</p><p>been secretary.) Both Rousselle and Caveney asked the voters to vote for the other</p><p>person. Rousselle was elected.</p><p><br>Co-President: Bob Ballard</p><p>Co-President: Michael Porcelli</p><p>Sec./Treas.: Rex Williams</p><p>Scholastic Coordinator: Nick Matta</p><p>USCF Delegate: Leila D’Aquin</p><p>USCF Alternate Delegate: Don Webster</p><p>New Orleans Area Board Rep.: James Rousselle</p><p>Baton Rouge Area Board Rep.: Mark Morreale</p><p>Lafayette Area Board Rep.: Tommy LeBlanc</p><p>North Louisiana Board Rep.: David Gaston</p><p>Lake Charles Area Board Rep.: Vacant/No Members Present</p><p><br>9. New Business:</p><p><br>Troendle announced the Cajun Chess upcoming tournament schedule: the U.S. Class</p><p>Championships in Houston on November 10-12, 2017, the New Orleans Open in</p><p>Kenner on December 26-30, 2017, and the U.S. Junior &amp; Senior Opens in Kenner</p><p>on June 16-18, 2018.</p><p><br>The membership unanimously passed a resolution to allow the board to donate up to</p><p>$1,000 to local chess clubs that had lost equipment and other assets due to</p><p>hurricanes.</p><p><br>2005 State Champion Eryk Hargrove moved that newly elected scholastic</p><p>coordinator Matta not be allowed to represent the LCA with blue or green</p><p>hair. Everyone had a good chuckle, and no action was taken.</p><p><br>Rouselle moved that Caveney receive a lifetime LCA membership for his</p><p>contributions to Louisiana Chess. The motion was unanimously passed. (Thank you</p><p>to all for this, it is appreciated.)</p><p><br>Newly-elected Co-President Bob Ballard moved that LCA dues be reduced to $10</p><p>per year for adults. There were many comments by the membership on this proposal,</p><p>very few of which agreed with any other comments. The motion was tabled for</p><p>future debate.</p><p><br>The meeting was then adjourned---in time to start the next round on time.</p>');
INSERT INTO "governance_documents" ("id","category","title","filename","file_url","doc_date","year","created_at","content") VALUES('ec42888c49854a70','minutes','LCA Meeting Minutes 2018',NULL,NULL,'2018-09-01',NULL,'2026-07-16 06:24:52','<p>MINUTES OF 2018 LOUISIANA CHESS ASSOC. GENERAL MEMBERSHIP MEETING</p><p><br>Saturday, September 1, 2018 – Baton Rouge, MINUTES</p><p><br>The meeting was called to order by co-Presidents Bob Ballard and Michael Porcelli at 2:09 p.m.</p><p>First business is the Treasurer’s Report.</p><p><br>TREASURER’S REPORT</p><p><br>Secretary/Treasurer Rex Williams reported that the current balance in the LCA account is</p><p>$7,466.80. The unusually large amount is mainly accounted for by the number of players who</p><p>attended the 2018 State Scholastic Championship (expenditures during the past year totaled</p><p>$2,200 for stipends given to the Louisiana representatives who attended the national chess</p><p>tournaments.) The Secretary/Treasurer advised that he could not give an accurate accounting of</p><p>the LCA balance because he still needs a list of names and accounting information for the new</p><p>LCA members from this year’s state scholastic tournament and Tournament of Champions which</p><p>were held in April and June, respectively. When Co-President Ballard pressed Mr. Matta for a</p><p>date that he would have that info to Mr. Williams since it had already been 4-1/2 months and</p><p>nothing had been turned in, which was already an unacceptable period of time, State Scholastic</p><p>Coordinator Nick Matta advised that he had a lot of things on his plate and that his school</p><p>coaching job was starting next week, but he would have that info to Mr. Williams by the end of</p><p>this month (Sept., 2018). It was mentioned by Mr. Matta and Ms. Leila D’Aquin that all stipends</p><p>paid to the representatives this year were covered by the amount of money brought in to the LCA</p><p>by the state scholastic championship entry fees and LCA scholastic memberships.</p><p><br>CO-PRESIDENTS’ REPORTS</p><p><br>Co-President Michael Porcelli stated that the net increase in the LCA treasury was due to better</p><p>scholastic involvement through the Celerity Schools in Baton Rouge which resulted in better</p><p>attendance at the state scholastic tournament along with the fact that Baton Rouge chess has been</p><p>more active as the Baton Rouge Paul Morphy was held again in addition to a few other chess</p><p>tournaments in and around the Baton Rouge area.</p><p>Co-President Bob Ballard did not have anything to add to Co- President Porcelli’s report.</p><p><br>SCHOLASTIC COORDINATOR’S REPORT</p><p><br>Scholastic Coordinator Nick Matta reported that there were 194 players in this year’s state</p><p>scholastic tournament, and that’s why the stipends were able to be increased from $300 each to</p><p>$550 each for the following representatives: Denker, Barber, Girls and Senior. He also stated</p><p>that he changed the format for choosing the representatives by hosting a second tournament, the</p><p>“Tournament of Champions,” on a weekend in June. The following players won their divisions</p><p>and represented Louisiana at their respective national tournaments in August:</p><p><br>Denker representative – Eli Karp</p><p>Barber representative – Minh Binh Tran</p><p>Girls representative – Sana Baig</p><p>Senior representative – Ramon Tagorda</p><p><br>US Chess Delegate Leila D’Aquin said that Mr. Tagorda, although third in line for the rep</p><p>position, made an excellent representative for Louisiana at the Senior national tournament and</p><p>won a “biggest upset” award. Eryk Hargrove accepted the position of Alternate LCA Delegate to</p><p>the U.S. Chess Federation.</p><p><br>US CHESS DELEGATE’S REPORT</p><p><br>US Chess Delegate Leila D’Aquin, attended several committee meetings at the U.S. Open in</p><p>August and reported the following:</p><p><br>The new Executive Director, Carol Meyer, a professional fundraiser for non-profit entities, is</p><p>focusing on building partnerships with various donors to obtain more funding for promoting</p><p>chess in broader horizons such as nursing homes, introducing it to Alzheimer’s patients in</p><p>hospitals, and finding other places where instructional chess activities can be beneficial to the</p><p>whole community. Contributions to US Chess are getting more and more important, and Dan</p><p>Lucas, who has been promoted from Editor of Chess Life to Director of Communications, will</p><p>work with state associations to get the word out to local communities about these initiatives.</p><p><br>LCA REGIONAL REPRESENTATIVE REPORTS</p><p><br>Mark Morreale and Tommy LeBlanc were the only two current delegates attending the meeting.</p><p><br>Tommy LeBlanc advised that the Lafayette Chess Club has been growing nicely and that more</p><p>tournaments have been taking place in Lafayette, LA, including the Lafayette Open, the</p><p>MacManus Memorial Tournament and the Louisiana Open over Memorial Day Weekend.</p><p>It was also reported that Fred Boerman may be interested in the position of delegate to the LCA</p><p>from the Lake Charles area. However, since he was not in attendance at the meeting, he cannot</p><p>be confirmed for this position and there is another gentleman, Mr. Adam Landry, whose sons are</p><p>scholastic players from Lake Charles, who may also be interested in the regional delegate</p><p>position in the event no one else accepts. A consensus of the membership was that Mr. Boerman</p><p>would be approached first to become the Lake Charles rep and, if he refused, then Mr. Landry</p><p>would be asked to take the position.</p><p><br>Co-President Bob Ballard and Secretary/Treasurer Rex Williams recently visited the Lake</p><p>Charles Chess Club to find out if the club is flourishing and to keep them informed of current</p><p>events.</p><p><br>LCA OFFICER ELECTIONS</p><p><br>For the office of President, Stuart Collins nominated Eryk Hargrove who immediately declined.</p><p>Jace Etienne nominated Bob Ballard and that nomination was seconded by Tommy LeBlanc.</p><p>Co-President Michael Porcelli was nominated for the position but he immediately declined</p><p>saying he is moving out of the state. There being no other members interested in that position,</p><p>Mr. Ballard was elected President of the LCA by acclamation.</p><p><br>For the office of Vice-President, three candidates were nominated: Leila D’Aquin, Ken Ferguson</p><p>and Jeff York. There was some general discussion on what the job requires for the office of VP,</p><p>and basically it was determined that the position is mainly to take over in the event that the</p><p>President can no longer serve out his term. Other discussion was geared to the VP possibly being</p><p>the contact person between the LCA and the US Chess; Michael Tisserand pointed out that the</p><p>Delegate is already the contact person. Each candidate was given a chance to say a few words</p><p>and then left the room before the voting took place, and the result was that Leila D’Aquin was</p><p>elected Vice President of the LCA.</p><p><br>For the office of Scholastic Coordinator, there were two nominees: Nick Matta and Ken</p><p>Ferguson. Both candidates were allowed to say a few words about how they would handle the</p><p>position prior to leaving the room for the voting process. The result was that Nick Matta was re-</p><p>elected to the position of Scholastic Coordinator of the LCA.</p><p><br>For regional delegates to the LCA, the following members accepted the positions:</p><p><br>New Orleans Area - Ken Ferguson</p><p>Baton Rouge Area - Mark Morreale</p><p>Lafayette Area - Tommy LeBlanc</p><p>Lake Charles - Position will first be offered to Fred Boerman, then to Mr. Landry if</p><p>Fred declines. *</p><p>North Louisiana - David Gaston, current rep but not present, will be asked to take the position</p><p>again.</p><p>*[NOTE: After the meeting Mr. Fred Boerman was contacted and accepted the position.]</p><p><br>NEW BUSINESS</p><p><br>Secretary/Treasurer Rex Williams expressed his discontent with the fact that he is not receiving</p><p>reports on a timely basis and requested that those who handle LCA tournaments in the future</p><p>please do a better job with getting him the information he needs to pay out stipends, send out</p><p>membership cards, etc.</p><p><br>Co-President Michael Porcelli brought up the question as to whether the State Scholastic</p><p>Coordinator has the authority to change the format of the state scholastic championship to a 2-</p><p>tournament event as was done this year with the regular state tournament being held in April and</p><p>a Tournament of Champions being held in June. Adam Caveney said that this has been a gray</p><p>area for some time, as the by-laws only state that the Scholastic Coordinator has the authority to</p><p>either have another entity do the state championship or do it under the LCA, but it doesn’t really</p><p>state anything about his authority to change the format of the event. Eryk Hargrove made a</p><p>motion that having two tournaments should be a Board-level decision and, if this results in a tie,</p><p>then the final decision should rest with the State Scholastic Coordinator. After a brief discussion,</p><p>this motion passed.</p><p><br>Ken Ferguson brought up the fact that there was no U1000 section in the high school section in</p><p>the original state championship in April which made for an odd situation for some of the weaker</p><p>high school players. State Scholastic Coordinator Nick Matta responded that he looked at the</p><p>high school sections of previous events and the attendance was so low in the sub-sections</p><p>(U1000 or (U1200) that he saw no reason to purchase trophies for a section with so few players.</p><p><br>Eryk Hargrove began a discussion on having more advance notice of events like the state</p><p>scholastic championship and that such an important state event should be advertised in Chess</p><p>Life magazine at least for one issue, preferably two. State Scholastic Coordinator Matta</p><p>responded that next year will be different, that he already has a date in mind for the original</p><p>event (March 30, 2019), and that the Tournament of Champions event will be sometime in April</p><p>(prior to the end of the school year) so as not to conflict with any national scholastic events, any</p><p>other chess events in Louisiana, or with any ACTs, SATs, or other school testing dates.</p><p><br>Newly elected LCA Vice President Leila D’aquin made a motion that the LCA Board meet at</p><p>least every other month, either in person, by phone, or by some alternative internet meeting</p><p>method (i.e., skype). She advised that, in her opinion, this is the only way to keep an</p><p>organization going and the lines of communication open so that everyone knows what is going</p><p>on and the LCA can plan for the future. After some discussion the motion was amended that a</p><p>rule require the board to meet at least 5 times per year in addition to the annual membership</p><p>meeting, and the amended motion was seconded, voted on and passed.</p><p><br>With this discussion over, Vice President D’Aquin moved that the meeting be adjourned. One of</p><p>the present members seconded the motion.</p><p><br>The 2018 Louisiana Chess Association Membership Meeting was adjourned at 3:21 p.m.</p><p><br>Respectfully submitted,</p><p>____________________</p><p>Rex Williams</p><p>LCA Secretary/Treasurer</p>');
INSERT INTO "governance_documents" ("id","category","title","filename","file_url","doc_date","year","created_at","content") VALUES('2d2fcb92e6454abb','minutes','LCA Meeting Minutes 2023',NULL,NULL,'2023-09-03',NULL,'2026-07-16 06:27:37','<p>Minutes</p><p>Louisiana Chess Association Business Meeting</p><p>September 3, 2023</p><p><br>President Schneider called the meeting to order at 3:35 p.m. with 14 members attending</p><p>in person and 4 participating via Zoom. She began by requesting a moment of silence in</p><p>memory of Bob Ballard who passed away in late December.</p><p><br>In Old Business, Secretary/Treasurer D’Aquin noted that her predecessor was not</p><p>present at the 2022 Membership Meeting, there are no minutes, and that there was</p><p>confusion regarding whether any effective date was selected for the dues change</p><p>discussed at that meeting. This year, members were told that the minimum dues</p><p>required to renew is $5 but that we hoped they would pay $15 because $5 dues will not</p><p>raise sufficient funds to pay for the organization’s very barest necessities. Clarification</p><p>and an adjustment to the dues structure will be discussed as New Business.</p><p><br>Board Members next delivered their reports.</p><p><br>President Schneider said the major focus of the year was a return to normalcy. To that</p><p>end, the board held regular meetings and revived more LCA-sponsored over-the-board-</p><p>events, including the Scholastic Kickoff, the Pro-Am, an MLK scholastic that ran</p><p>alongside the Pro-Am, the State Scholastic Championship, and the Tournaments of</p><p>Champions Qualifier. She encouraged clubs and organizers to be sure to check the</p><p>clearinghouse to avoid having scheduling conflicts and to provide the website</p><p>administrator with flyers re upcoming events, reports on events conducted, and other</p><p>chess news. She also discussed her experience doing a six-minute chess lesson</p><p>feature for the Great Day Louisiana TV program. A motion was made and seconded,</p><p>and the report was unanimously accepted.</p><p><br>Vice President Chris Girardo reported on his efforts to formalize the clearinghouse</p><p>process and encourage its use. He also reported on college chess development in the</p><p>state. A motion was made and seconded, and the report was unanimously accepted.</p><p><br>Secretary/Treasurer D’Aquin reviewed the Treasurer’s Report that is attached. A motion</p><p>was made and seconded, and the report was unanimously accepted.</p><p><br>Don Runge read a report from Scholastic Coordinator Isabella Runge, describing the</p><p>successful Kickoff Scholastic tournament held in New Orleans in October, the well-</p><p>attended Scholastic Championship held in Baton Rouge, and the Tournaments of</p><p>Champions qualifiers at which Mihn Tran was selected to be the state’s Denker</p><p>representative; Matteo Runge, Barber rep; Sana Baig, Haring rep; Wyatt Sledge,</p><p>Rockefeller Rep, and Ramon Tagorda, Irwin Senior rep. Louisiana’s full delegation</p><p>competed in the Tournaments of Champions during the US Open in Grand Rapids,</p><p>Michigan.</p><p><br>Area Reps Don Runge for Greater Baton Rouge, Matthew Moore for North Louisiana,</p><p>and Jordy Pujol for South Central each reported. Baton Rouge has seen an expansion</p><p>of interested schools and has a new program at the Bluebonnet Library. North Louisiana</p><p>has several active clubs; the Monroe &amp; Ruston Clubs hold tournaments regularly,</p><p>alternating hosting duties. Shreveport/Bossier has a new club that is pretty active and</p><p>has about 20 participants in tournaments.</p><p><br>The Lake Charles/Southwest rep was not in attendance, but Andy Rivera who operates</p><p>Casa de Ajedrez in Sulphur reported on the substantial building of the chess community</p><p>in the region. His group has 35 active OTB players and 80 online players. Among other</p><p>activities, they have OTB tournaments every 3 months with sponsored prizes; 56</p><p>children learned to play in July; they teach chess to older adults at a senior center; and</p><p>Casa de Ajedrez has established a team competition with a perpetual trophy against a</p><p>group from Beaumont in which the Case de Ajedrez team recently prevailed. The</p><p>members gave Andy a round of applause for reestablishing the chess community in the</p><p>Lake Charles area which had been struggling since Hurricane Laura.</p><p><br>The Greater New Orleans rep was not in attendance, but President Schneider</p><p>discussed the increasing scholastic activity; several clubs meeting regularly; and</p><p>requests from a coffee shop to establish another weekly unrated chess night.</p><p><br>Motions to accept were offered and all of the area reports were accepted.</p><p><br>Leila D’Aquin gave a brief report on the US Chess Delegate’s meeting and explained</p><p>the Safe Play training which will be required of all Tournament Directors. Caveney</p><p>moved to accept the report, Schneider seconded, and the report was accepted.</p><p><br>In New Business, motions were offered to define the dues year and to set the dues</p><p>levels at $15 adult, $5 scholastic, $25 family, and $10 for seniors over age 65. Caveney</p><p>suggested that a single-event membership of $5 be offered for LCA-sanctioned events</p><p>other than the State Championship so that those joining later in the year have an option</p><p>other than paying a full year’s dues. After much discussion, it was agreed that the dues</p><p>year shall run from September 1 – August 31, for the four dues levels of $15, $5, $25,</p><p>and $10 and a special $5 single-event membership will be offered as described above.</p><p><br>Next, D’Aquin offered a motion to adopt a 6 year or 5 year rotating schedule for the</p><p>State Championship to be held in the different regions of the state as defined in the</p><p>Bylaws. After much discussion, a straw poll was taken that indicated the 6 year</p><p>schedule in which the New Orleans Metro region would appear twice and the other 4</p><p>regions once each was the body’s preference. The group discussed parameters that</p><p>would allow the President flexibility to depart from the schedule should there be a year</p><p>in which the president and area rep working with clubs and groups in that year’s</p><p>designated region were unable to secure a site and initiate planning for the tournament</p><p>by March 1; in such a case, the president would have discretion to schedule the event</p><p>outside of the designated region with the championship returning to the prescribed</p><p>schedule the following year. Given that the championship was held in New Orleans in</p><p>2022 and in Lafayette in 2023, the schedule hereafter will be :</p><p><br>2024 &amp; every 6th year following, North Louisiana</p><p>2025 &amp; every 6th year following, New Orleans Metro</p><p>2026 &amp; every 6th year following, Lake Charles/Southwest</p><p>2027 &amp; every 6th year following, Baton Rouge/East Central</p><p>2028 &amp; every 6th year following, New Orleans Metro</p><p>2029 &amp; every 6th year following, Lafayette/South Central</p><p><br>On motion made and seconded, this schedule and plan were adopted.</p><p><br>Eryk Hargrove moved that a rule be adopted requiring that the state championship site</p><p>and schedule be announced by the president 3 months prior to Labor Day weekend.</p><p>This motion was seconded and adopted.</p><p><br>Vice President Chris Girardo presided over elections of the 2023-24 board and</p><p>delegates.</p><p><br>Schneider nominated Nick Matta for president, D’Aquin seconded, and there being no</p><p>other nominations, Matta was elected by acclamation.</p><p><br>Matta nominated Adriana Schneider for vice president, Jace Etienne seconded, and</p><p>there being no other nominations, Schneider was elected by acclamation.</p><p><br>D’Aquin nominated Matthew Moore for secretary/treasurer, Schneider seconded.</p><p>Hargrove nominated Don Runge for secretary/treasurer, Matta seconded. After making</p><p>brief remarks about their qualifications, the candidates left the room/Zoom, a vote was</p><p>taken and Moore was elected.</p><p><br>D’Aquin nominated Isabella Runge for scholastic coordinator, Matta seconded, and</p><p>there being no other nominations, Isabella Runge was elected by acclamation.</p><p><br>Two delegates and two alternate delegates to US Chess were selected, Schneider and</p><p>Andrew Squitiro are the delegates and alternates are Matthew Billings and Eryk</p><p>Hargrove.</p><p><br>Each of the regions then elected a representative. Selected were Matthew Billings, New</p><p>Orleans Metro; Chris Girardo, North; Andy Rivera, Lake Charles/Southwest; Don</p><p>Runge, Baton Rouge/EastCentral; and Stewart Krielow, Lafayette/South Central.</p><p><br>There being no further business, Caveney moved to adjourn, all cheered, and the</p><p>meeting adjourned at 4:48 p.m.</p>');
INSERT INTO "governance_documents" ("id","category","title","filename","file_url","doc_date","year","created_at","content") VALUES('097bf576bcd24ca8','minutes','LCA Meeting Minutes 2024',NULL,NULL,'2024-09-02',NULL,'2026-07-16 06:29:30','<p>Minutes</p><p>Louisiana Chess Association Business Meeting</p><p>September 2, 2024</p><p><br>President Matta called the meeting to order.</p><p><br>Members reviewed the previous minutes from September 3, 2023. Jace Etienne moved to</p><p>approved. Steward Krielow seconded. The minutes were approved by acclamation.</p><p><br>President Matta delivered his report. He highlighted more LCA tournaments in many diIerent</p><p>regions: Marksville, Pro-Am, Paul Morphy, State Championship. One of his goals was to bring back</p><p>tournaments that had not been held since COVID including the Pro-Am and the Morphy. He noted</p><p>that the Paul Morphy tournament brough in GM Alex Linderman and may partner with him in the</p><p>future.</p><p><br>President Matta also reported on the Scholastic State Championship. It had the largest turnout of</p><p>any tournament. Sponsorship was obtained from a parent of a player to cover the cost of trophies</p><p>and medals. As a result of this, the LCA was able to increase the stipend for national</p><p>representatives.</p><p><br>Leila D’Aquin delivered a report about the TOC qualifier tournament which she organized. It was</p><p>well attended. Those who attended that national tournaments were acknowledged.</p><p><br>Vice President Schneider delivered her report. She assisted three schools start programs. One</p><p>hosted the state scholastic championship. She was able to locate four new clubs in New Orleans</p><p>area. She noted that there is still a need for people to help run and create clubs. Coaches are also a</p><p>need on the Northshore. She noted that the Vice President is supposed to run a clearing house for</p><p>tournaments. She requested that tournament organizers let the Vice President know when</p><p>tournaments are held. She plans to create a calendar on the website with all tournaments (club</p><p>level and LCA). She pointed out that we don’t want tournaments with the same name. There was an</p><p>issue with two tournaments named Paul Morphy this year.</p><p><br>Adriana Schneider and Andrew Squitiro were delegates to the US Chess Delegate’s meeting in</p><p>Norfolk, VA. They reported on some of the activities of the delegates. It was requested that national</p><p>championships be added to the LCA calendar. There are also two new invitational championships.</p><p>The Maurice Ashley K-3 championship will be added by 2026, and the Paul Morphy K-1 will be added</p><p>by 2030.</p><p><br>Secretary/Treasurer Moore delivered the Treasury Report. It is attached. Leila D’Aquin moved to</p><p>accept, Adam Caveny seconded. The report was approved by acclamation.</p><p><br>Leila D’Aquin nominated Stewart Krielow for president. Jace Etienne seconded. Krielow was elected</p><p>by acclamation.</p><p><br>Vice president – D’Aquin nominated Adrienne Schneider for Vice President. Nick Matta seconded.</p><p>Schneider was elected by acclamation.</p><p><br>Scholastic coordinator – Matta nominated Maddie Robison for Scholastic Coordinator. D’Aquin</p><p>seconded. Robinson was elected by acclamation.</p><p><br>Sec/Treasurer – Matthew Moore nominated Don Runge for Secretary/Treasurer. Matta seconded.</p><p>Runge was elected by acclamation.</p><p><br>Each of the regions present elected a representative. Selected were Richard Campbell, New</p><p>Orleans Metro; Jude Coomer, Lafayette/South Central; Andy Rivera, Lake Charles/Southwest; Jerry</p><p>Kennedy, North. No representatives from Baton Rouge were present.</p><p><br>Two delegates and two alternate delegates to the US Chess 2025 Delegates Meeting were selected.</p><p>Schneider and Squitiro are the delegates and Krielow and Anh Le are the alternates.</p><p><br>Andy Rivera delivered the Lake Charles/Southwest area report. There are 15 USCF members in his</p><p>club. He took members to the Pro-Am, monthly tournaments in Lafayette, and team tournaments v</p><p>Lafayette (10 v. 10). He hosted two USCF rated tournaments in Lake Charles. These tournaments</p><p>are low cost to get people experience in the USCF world. Beaumont will hold its first USCF rated</p><p>tournament next month which Andy will TD. Andy holds a monthly Cici’s Pizza tournament and</p><p>wants to do online rated tournaments.</p><p><br>Stewart Krielow delivered the Lafayette/South Central area report. He noted that Lafayette clubs</p><p>were disjointed. He joined every club and met the members. Through this he found a way to get all</p><p>the clubs to play together. He started an umbrella club called Pelican Chess. The club runs free</p><p>rated tournaments every month. These are so successful that they are running out of space. The</p><p>last tournament had 23 people. They also hosted a team tournament with Lake Charles. Krielow</p><p>stated that he has visited the Marshall, St. Louis, and San Diego chess clubs to see what they are</p><p>doing.</p><p><br>Matthew Moore delivered the North area report. He noted that the Ruston and Shreveport/Bossier</p><p>clubs continue to host USCF tournaments. Regular meet ups are happening in Shreveport/Bossier,</p><p>Ruston, and Monroe.</p><p><br>Business having concluded, D’Aquin moved to adjourn. Matta seconded and the motion was</p><p>approved by acclamation.</p>');
