PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE clubs (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  city TEXT NOT NULL,
  location TEXT,
  description TEXT,
  meeting_schedule TEXT,
  contact_email TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
, image_url TEXT DEFAULT NULL, region TEXT DEFAULT NULL, color TEXT DEFAULT '#c8a94a');
CREATE TABLE tournaments (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  location TEXT NOT NULL,
  venue TEXT,
  date TEXT NOT NULL,
  end_date TEXT,
  entry_fee REAL NOT NULL,
  sections TEXT NOT NULL,
  rounds INTEGER NOT NULL,
  max_players INTEGER,
  status TEXT NOT NULL
    CHECK (status IN ('upcoming', 'active', 'completed')),
  description TEXT,
  registration_deadline TEXT,
  club_id TEXT REFERENCES clubs(id),
  created_by TEXT REFERENCES members(id),
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
, registration_status TEXT NOT NULL DEFAULT 'draft'
  CHECK (registration_status IN ('draft', 'open', 'closed')), registration_opens_at TEXT, reminder_1_days_before INTEGER DEFAULT 7, reminder_1_enabled INTEGER DEFAULT 1, reminder_2_days_before INTEGER DEFAULT 1, reminder_2_enabled INTEGER DEFAULT 1, is_rated INTEGER NOT NULL DEFAULT 1, is_visible INTEGER NOT NULL DEFAULT 1, round_schedule TEXT, registration_closes_at TEXT, custom_details TEXT, registration_url TEXT DEFAULT NULL, eligibility TEXT DEFAULT NULL, organizer TEXT DEFAULT NULL, time_control TEXT DEFAULT NULL);
CREATE TABLE registrations (
  id TEXT PRIMARY KEY,
  tournament_id TEXT NOT NULL REFERENCES tournaments(id),
  member_id TEXT NOT NULL REFERENCES members(id),
  section TEXT NOT NULL,
  payment_status TEXT NOT NULL DEFAULT 'pending'
    CHECK (payment_status IN ('pending', 'paid', 'refunded')),
  registered_at TEXT NOT NULL DEFAULT (datetime('now'))
, bye_rounds TEXT, withdrawn_at TEXT, checked_in_at TEXT);
CREATE TABLE club_officers (
  id TEXT PRIMARY KEY,
  club_id TEXT NOT NULL REFERENCES clubs(id),
  member_id TEXT NOT NULL REFERENCES members(id),
  role TEXT NOT NULL
    CHECK (role IN ('president', 'secretary', 'treasurer', 'rep')),
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE club_news (
  id TEXT PRIMARY KEY,
  club_id TEXT NOT NULL REFERENCES clubs(id),
  title TEXT NOT NULL,
  news_date TEXT NOT NULL,
  excerpt TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE tournament_directors (
  tournament_id TEXT NOT NULL REFERENCES tournaments(id) ON DELETE CASCADE,
  member_id TEXT NOT NULL REFERENCES members(id) ON DELETE CASCADE,
  assigned_at TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (tournament_id, member_id)
);
CREATE TABLE tournament_reminders (
  id TEXT PRIMARY KEY,
  member_id TEXT NOT NULL REFERENCES members(id) ON DELETE CASCADE,
  tournament_id TEXT NOT NULL REFERENCES tournaments(id) ON DELETE CASCADE,
  email TEXT NOT NULL,
  sent_registration_open INTEGER NOT NULL DEFAULT 0,
  sent_week_before INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE (member_id, tournament_id)
);
CREATE TABLE tournament_attendee_reminders (
  id TEXT PRIMARY KEY,
  tournament_id TEXT NOT NULL REFERENCES tournaments(id) ON DELETE CASCADE,
  member_id TEXT NOT NULL REFERENCES members(id) ON DELETE CASCADE,
  reminder_number INTEGER NOT NULL,
  sent_at TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE (tournament_id, member_id, reminder_number)
);
CREATE TABLE contact_messages (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  email TEXT NOT NULL,
  subject TEXT NOT NULL,
  body TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'unread'
    CHECK (status IN ('unread', 'read', 'replied')),
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE support_tickets (
  id TEXT PRIMARY KEY,
  member_id TEXT REFERENCES members(id) ON DELETE SET NULL,
  name TEXT NOT NULL,
  email TEXT NOT NULL,
  subject TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'open'
    CHECK (status IN ('open', 'in_progress', 'resolved')),
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE support_messages (
  id TEXT PRIMARY KEY,
  ticket_id TEXT NOT NULL REFERENCES support_tickets(id) ON DELETE CASCADE,
  sender_id TEXT,
  sender_type TEXT NOT NULL CHECK (sender_type IN ('member', 'admin', 'guest')),
  body TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE d1_migrations(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE board_members (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(8)))),
  role TEXT NOT NULL,
  name TEXT NOT NULL,
  email TEXT,
  sort_order INTEGER DEFAULT 0,
  created_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE governance_documents (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(8)))),
  category TEXT NOT NULL, -- 'bylaws' | 'rules' | 'minutes' | 'treasurer' | 'amendments'
  title TEXT NOT NULL,
  filename TEXT,
  file_url TEXT,
  doc_date TEXT,
  year INTEGER,
  created_at TEXT DEFAULT (datetime('now'))
, content TEXT);
CREATE TABLE clearinghouse (
  id            TEXT PRIMARY KEY,
  name          TEXT NOT NULL,
  start_date    TEXT NOT NULL,
  end_date      TEXT,
  organizer     TEXT,
  city          TEXT,
  state         TEXT,
  venue         TEXT,
  rating_system TEXT,
  eligibility   TEXT,
  contact       TEXT,
  link          TEXT,
  is_lca        INTEGER DEFAULT 0,
  synced_at     TEXT DEFAULT (datetime('now'))
);
CREATE TABLE members (
  id TEXT PRIMARY KEY,
  email TEXT NOT NULL,
  full_name TEXT NOT NULL,
  uscf_id TEXT,
  membership_status TEXT NOT NULL DEFAULT 'pending'
    CHECK (membership_status IN ('active', 'expired', 'pending')),
  membership_expiry TEXT,
  role TEXT NOT NULL DEFAULT 'member'
    CHECK (role IN ('member', 'club_rep', 'tournament_director', 'lca_admin', 'guest')),
  club_id TEXT REFERENCES clubs(id),
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  uscf_rating INTEGER,
  uscf_rating_updated_at TEXT
, membership_type TEXT DEFAULT NULL);
CREATE TABLE payments (
  id TEXT PRIMARY KEY,
  member_id TEXT REFERENCES members(id),
  amount REAL NOT NULL,
  type TEXT NOT NULL CHECK (type IN ('membership', 'tournament', 'donation')),
  reference_id TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending', 'completed', 'failed')),
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  stripe_session_id TEXT,
  stripe_payment_intent TEXT
);
CREATE TABLE tournament_games (
  id TEXT PRIMARY KEY,
  tournament_id TEXT NOT NULL REFERENCES tournaments(id) ON DELETE CASCADE,
  round INTEGER NOT NULL,
  board INTEGER NOT NULL,
  section TEXT NOT NULL,
  white_member_id TEXT REFERENCES members(id),
  black_member_id TEXT REFERENCES members(id),
  result TEXT NOT NULL DEFAULT 'pending'
    CHECK (result IN ('1-0', '0-1', '1/2-1/2', '1-0 F', '0-1 F', '0-0 F', 'bye', 'bye-half', 'pending')),
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE (tournament_id, round, board, section)
);
CREATE TABLE email_campaigns (
  id TEXT PRIMARY KEY,
  subject TEXT NOT NULL,
  body_html TEXT NOT NULL,
  filter_json TEXT NOT NULL,          -- {"all":true} or {"roles":[],"clubIds":[],"membershipStatuses":[]}
  total_recipients INTEGER NOT NULL DEFAULT 0,
  sent_count INTEGER NOT NULL DEFAULT 0,
  failed_count INTEGER NOT NULL DEFAULT 0,
  status TEXT NOT NULL DEFAULT 'sending' CHECK (status IN ('sending', 'completed', 'failed')),
  created_by TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  completed_at TEXT,
  FOREIGN KEY (created_by) REFERENCES members(id)
);
CREATE TABLE email_campaign_recipients (
  id TEXT PRIMARY KEY,
  campaign_id TEXT NOT NULL,
  member_id TEXT NOT NULL,
  email TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'sent', 'failed')),
  error TEXT,
  sent_at TEXT,
  FOREIGN KEY (campaign_id) REFERENCES email_campaigns(id),
  FOREIGN KEY (member_id) REFERENCES members(id)
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_tournaments_status ON tournaments(status);
CREATE INDEX idx_tournaments_club_id ON tournaments(club_id);
CREATE INDEX idx_registrations_member_id ON registrations(member_id);
CREATE INDEX idx_registrations_tournament_id ON registrations(tournament_id);
CREATE INDEX idx_club_officers_club_id ON club_officers(club_id);
CREATE INDEX idx_club_news_club_id ON club_news(club_id);
CREATE INDEX idx_tournament_directors_member_id ON tournament_directors(member_id);
CREATE INDEX idx_tournament_reminders_tournament_id
  ON tournament_reminders(tournament_id);
CREATE INDEX idx_tournament_reminders_member_id
  ON tournament_reminders(member_id);
CREATE INDEX idx_attendee_reminders_tournament_id
  ON tournament_attendee_reminders(tournament_id);
CREATE INDEX idx_support_tickets_member_id
  ON support_tickets(member_id);
CREATE INDEX idx_support_tickets_status
  ON support_tickets(status);
CREATE INDEX idx_support_messages_ticket_id
  ON support_messages(ticket_id);
CREATE INDEX idx_clearinghouse_start_date ON clearinghouse(start_date);
CREATE INDEX idx_clearinghouse_state ON clearinghouse(state);
CREATE INDEX idx_members_email ON members(email);
CREATE INDEX idx_members_role ON members(role);
CREATE INDEX idx_members_club_id ON members(club_id);
CREATE INDEX idx_payments_member_id ON payments(member_id);
CREATE INDEX idx_tournament_games_tournament_id ON tournament_games(tournament_id);
CREATE INDEX idx_campaign_recipients_campaign ON email_campaign_recipients(campaign_id);
CREATE INDEX idx_campaign_recipients_pending ON email_campaign_recipients(campaign_id, status);
